/**
 * How a competence level is painted.
 *
 * Competence-level colours depend on the level scale in the loaded data and are
 * generated by `competenceLevelColors`. Here they become published tokens
 * (`paletteTokens.js`): a renderer paints the level's `--competence-level-…` token.
 * Every other chart colour is a stylesheet token the renderers reference directly.
 */

import { slugifyCompetenceToken } from './competenceLevelPalette.js';
import { getBandPaint } from './competenceLevelColors.js';
import { paletteToken } from './paletteTokens.js';

/**
 * The colour a competence level is painted, as a `var()` of its published token (see
 * `paletteTokens.js`); values that are not registered levels take the neutral bar color.
 * @param {import('./competenceLevelPalette.js').CompetenceLevelPalette} palette
 * @param {string|number} level
 * @param {string} [scaleId] - Which ladder `level` belongs to. Needed only where one page
 *   holds two ladders sharing a level name; without it the
 *   answer is the scale that registered the name last.
 * @returns {string} The level's `var()`, or the neutral bar colour's.
 */
export function getCompetenceColor(palette, level, scaleId) {
    return (
        getCompetenceAppearance(palette, level, scaleId)?.baseColor ?? 'var(--default-bar-color)'
    );
}

/**
 * The appearance of a competence level, or `null` when the value is not a registered
 * level, which is how renderers tell competence-level fields apart from gender /
 * richtig-falsch fields.
 *
 * The fill and its label ink are `var()`s of the level's published tokens. Every level
 * resolves to one solid color (see `getLevelColors`). Memoised per registration: it runs
 * per drawn segment, and the answer depends only on the registered scales.
 * @param {import('./competenceLevelPalette.js').CompetenceLevelPalette} palette
 * @param {string|number} level
 * @param {string} [scaleId] - Which ladder `level` belongs to; see `getCompetenceColor`
 * @returns {import('./competenceLevelPaint.js').CompetenceAppearance|null}
 */
export function getCompetenceAppearance(palette, level, scaleId) {
    // `${scaleId}` keeps "no scale" (the bare-name lookup) apart from any scale id.
    return palette.memo(`appearance:${scaleId}\x00${level}`, () => {
        const entry = palette.getCompetenceLevelEntry(level, scaleId);
        if (!entry) {
            return null;
        }

        const name = `--competence-level-${cssIdent(entry.scaleId)}-${cssIdent(entry.name)}`;
        const paint = (/** @type {'light'|'dark'} */ scheme) =>
            getBandPaint(palette, entry.name, entry.scaleId, scheme);
        return {
            normalizedLevel: entry.name,
            baseColor: paletteToken(name, (scheme) => paint(scheme)?.color ?? null),
            ink: paletteToken(`${name}-ink`, (scheme) => paint(scheme)?.ink ?? null),
            patternKey: slugifyCompetenceToken(entry.name),
        };
    });
}

/**
 * A scale id or level name as part of a custom-property name: letters and digits kept,
 * every other character spelled as `_<four hex digits>`, so two distinct names never share a token.
 * @param {string} value
 * @returns {string}
 */
function cssIdent(value) {
    // Fixed width: unpadded, `\x20` + `1` and `ȁ` would both spell `_201`.
    return value.replace(
        /[^a-zA-Z0-9]/g,
        (char) => `_${char.charCodeAt(0).toString(16).padStart(4, '0')}`,
    );
}
